import{c as a,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const n="/assets/Arange%E7%AE%97%E6%B3%95%E6%A1%86%E5%9B%BE.DcbjyvSs.png",A=JSON.parse('{"title":"Arange","description":"","frontmatter":{},"headers":[{"level":1,"title":"Arange","slug":"arange"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"实现原理","slug":"实现原理"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/索引计算/Arange-94.md","filePath":"api/SIMD-API/高阶API/索引计算/Arange-94.md"}'),r={name:"api/SIMD-API/高阶API/索引计算/Arange-94.md"};function d(i,t,o,p,c,h){return e(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="arange" tabindex="-1">Arange <a class="header-anchor" href="#arange" aria-label="Permalink to &quot;Arange&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>给定起始值，等差值和长度，返回一个等差数列。</p><h2 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h2><p>以float类型，ND格式，firstValue和diffValue输入Scalar为例，描述Arange高阶API内部算法框图，如下图所示。</p><p><strong>图 1</strong> Arange算法框图<br><img src="'+n+`" alt="" title="Arange算法框图"></p><p>计算过程分为如下几步，均在Vector上进行：</p><ol><li>等差数列长度8以内步骤：按照firstValue和diffValue的值，使用SetValue实现等差数列扩充，扩充长度最大为8，如果等差数列长度小于8，算法结束；</li><li>等差数列长度8至64的步骤：对第一步中的等差数列结果使用Adds进行扩充，最大循环7次扩充至64，如果等差数列长度小于64，算法结束；</li><li>等差数列长度64以上的步骤：对第二步中的等差数列结果使用Adds进行扩充，不断循环直至达到等差数列长度为止。</li></ol><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void Arange(const LocalTensor&lt;T&gt;&amp; dst, const T firstValue, const T diffValue, const int32_t count)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。不同型号支持的数据类型请参考支持的数据类型。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。dst的大小应大于等于count * sizeof(T)。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>firstValue</td><td>输入</td><td>等差数列的首个元素值。</td></tr><tr><td>diffValue</td><td>输入</td><td>等差数列元素之间的差值，应大于等于0。</td></tr><tr><td>count</td><td>输入</td><td>等差数列的长度。count&gt;0。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>当前仅支持ND格式的输入，不支持其他格式。</p></li><li><p>支持的数据类型</p><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t、half、int32_t、float、int64_t。</p><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int16_t、half、int32_t、float。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int16_t、half、int32_t、float。</p><p>Atlas 推理系列产品AI Core，支持的数据类型为：int16_t、half、int32_t、float。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/06_index/arange" target="_blank" rel="noreferrer">Arange样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dst：输出Tensor</span></span>
<span class="line"><span>// firstValue_：等差数列首个元素值</span></span>
<span class="line"><span>// diffValue_：等差数列的公差</span></span>
<span class="line"><span>// count_：等差数列的长度</span></span>
<span class="line"><span>AscendC::Arange&lt;T&gt;(dst, static_cast&lt;T&gt;(firstValue_), static_cast&lt;T&gt;(diffValue_), count_);</span></span></code></pre></div>`,24)])])}const g=a(r,[["render",d]]);export{A as __pageData,g as default};
